interface.definition:
a!localVariables(
  local!isOldVersion:if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    false,
    if(
      todatetime(ri!nomination.createdOn)<#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11589045",
      true,
      false)
  ),
  local!showDirectHire: and(
    or(
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!nomination.statusId),
      ri!nomination.statusId = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578065",
      isusermemberofgroups(
        ri!nomination.createdBy,
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922"
      )
    ),
    isusermemberofgroups(
      loggedInUser(),
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922"
    )
  ),
  local!positionTypes: index(
    ri!nominationTypes,
    wherecontains(
      #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3595745",
      tointeger(
        index(ri!nominationTypes, "refTypeId", {})
      )
    ),
    null
  ),
  local!subPositionTypes: if(
    and(
      ri!nomination.positionTypeId = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596692",
      not(ri!nomination.isDirectHire = true)
    ),
    remove(
      index(
        ri!subPositionTypes,
        wherecontains(
          ri!nomination.positionTypeId,
          tointeger(index(ri!subPositionTypes, "refId", {}))
        ),
        null
      ),
      wherecontains(
        #"_a-0000e6ca-52ed-8000-9bff-011c48011c48_3718018",
        tointeger(
          index(ri!subPositionTypes, "subPositionId", {})
        )
      )
    ),
    index(
      ri!subPositionTypes,
      wherecontains(
        ri!nomination.positionTypeId,
        tointeger(index(ri!subPositionTypes, "refId", {}))
      ),
      null
    )
  ),
  local!nonTraditionalRotationalTypeOther:#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11599196"(
    nonTradRotationId: {#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11742624"[10]},
  ),
  local!nonTraditionalRotationalTypes: append(#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11599196"(
    nonTradRotationId: {remove(#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11742624",#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11742624"[10])},
    fetchTotalCount: true),
    local!nonTraditionalRotationalTypeOther), 
  /*local!createdOnDate: if(*/
    /*rule!CAW_isBlank(ri!nomination.nominationId),*/
    /*null,*/
    /*index(*/
      /*index(*/
        /*rule!CAW_QE_getNomination(*/
          /*nominationId: ri!nomination.nominationId*/
        /*),*/
        /*"data",*/
        /*null*/
      /*),*/
      /*"createdOn",*/
      /*null*/
    /*)*/
  /*),*/
  #"SYSTEM_SYSRULES_cardLayout"(
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_radioButtonField"(
                label: "Is Candidate a Direct Hire?",
                choiceLabels: { "Yes", "No" },
                choiceValues: { true, false },
                value: ri!nomination.isDirectHire,
                saveInto: {
                  ri!nomination.isDirectHire,
                  a!save(
                    ri!nomination.isDirectHireInternal,
                    null
                  ),
                  a!save(ri!oldBu,null),
                  a!save(ri!oldOffice,null),
                  a!save(ri!nomination.employeeId, null),
                  a!save(ri!nomination.firstName, null),
                  a!save(ri!nomination.middleName, null),
                  a!save(ri!nomination.lastName, null),
                  a!save(ri!nomination.functionName, null),
                  a!save(ri!nomination.currentPML, null),
                  a!save(ri!nomination.levelName, null),
                  a!save(ri!nomination.originatingRegion, null),
                  a!save(
                    ri!nomination.otherOriginatingRegion,
                    null
                  ),
                  a!save(ri!nomination.originatingBU, null),
                  a!save(ri!nomination.otherOriginatingBU, null),
                  a!save(
                    ri!nomination.originatingHomeOffice,
                    null
                  ),
                  a!save(
                    ri!nomination.otherOriginatingHomeOffice,
                    null
                  ),
                  a!save(ri!nomination.returnRegion, null),
                  a!save(
                    ri!nomination.otherReturningRegion,
                    null
                  ),
                  a!save(ri!nomination.returnBU, null),
                  a!save(ri!nomination.otherReturningBU, null),
                  a!save(ri!nomination.returnHomeOffice, null),
                  a!save(
                    ri!nomination.otherReturningHomeOffice,
                    null
                  ),
                  a!save(ri!nomination.jobDescription, null),
                  a!save(ri!nomination.employeeEmail, null),
                  if(
                    ri!nomination.isDirectHire = true,
                    a!save(
                      ri!nomination.recommendedDppGroupId,
                      null
                    ),
                    {}
                  ),
                  if(
                    ri!nomination.isDirectHire = true,
                    a!save(
                      ri!nomination.dppGroupOtherComment,
                      null
                    ),
                    {}
                  ),

                },
                showWhen: local!showDirectHire,
                required: local!showDirectHire,
                choiceLayout: "COMPACT"
              ),
              #"SYSTEM_SYSRULES_radioButtonField"(
                label: "Is Direct Hire Internal or External?",
                choiceLabels: #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596529",
                choiceValues: { true, false },
                value: ri!nomination.isDirectHireInternal,
                saveInto: {
                  ri!nomination.isDirectHireInternal,
                  a!save(ri!oldBu,null),
                  a!save(ri!oldOffice,null),
                  a!save(ri!nomination.employeeId, null),
                  a!save(ri!nomination.firstName, null),
                  a!save(ri!nomination.middleName, null),
                  a!save(ri!nomination.lastName, null),
                  a!save(ri!nomination.functionName, null),
                  a!save(ri!nomination.currentPML, null),
                  a!save(ri!nomination.levelName, null),
                  a!save(ri!nomination.originatingRegion, null),
                  a!save(
                    ri!nomination.otherOriginatingRegion,
                    null
                  ),
                  a!save(ri!nomination.originatingBU, null),
                  a!save(ri!nomination.otherOriginatingBU, null),
                  a!save(
                    ri!nomination.originatingHomeOffice,
                    null
                  ),
                  a!save(
                    ri!nomination.otherOriginatingHomeOffice,
                    null
                  ),
                  a!save(ri!nomination.returnRegion, null),
                  a!save(
                    ri!nomination.otherReturningRegion,
                    null
                  ),
                  a!save(ri!nomination.returnBU, null),
                  a!save(ri!nomination.otherReturningBU, null),
                  a!save(ri!nomination.returnHomeOffice, null),
                  a!save(
                    ri!nomination.otherReturningHomeOffice,
                    null
                  ),
                  a!save(ri!nomination.jobDescription, null),
                  a!save(ri!nomination.employeeEmail, null),

                },
                required: ri!nomination.isDirectHire,
                showWhen: local!showDirectHire,
                disabled: not(ri!nomination.isDirectHire = true),
                choiceLayout: "COMPACT"
              ),
              #"SYSTEM_SYSRULES_dropdownField_v1"(
                label: "Position Type",
                placeholder: "-- Select Position Type --",
                choiceLabels: index(local!positionTypes, "description", null),
                choiceValues: index(local!positionTypes, "refId", null),
                value: ri!nomination.positionTypeId,
                saveInto: {
                  ri!nomination.positionTypeId,
                  a!save(ri!nomination.subPositionTypeId, null),
                  a!save(
                    ri!nomination.nonTraditionalTypeId,
                    null
                  ),
                  a!save(
                    ri!nomination.otherNonTraditionalRotationType,
                    null
                  ),
                  if(
                    ri!nomination.positionTypeId <> #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596692",
                    a!save(
                      ri!nomination.recommendedDppGroupId,
                      null
                    ),
                    {}
                  ),
                  if(
                    ri!nomination.positionTypeId <> #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596692",
                    a!save(
                      ri!nomination.dppGroupOtherComment,
                      null
                    ),
                    {}
                  ),
                  if(
                    ri!nomination.positionTypeId <> #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699",
                    {
                      a!save(
                        ri!nomination.isPotentialSec_FasbCandidate,
                        null
                      ),
                      a!save(ri!nomination.isAqspNomination, null)
                    },
                    {}
                  )
                },
                required: true,
                disabled: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!nomination.nominationTypeId)
              ),
              #"SYSTEM_SYSRULES_linkField"(
                links: #"SYSTEM_SYSRULES_reportLink"(
                  label: "Role Definitions",
                  report: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3196185",
                  openLinkIn: "NEW_TAB"
                )
                ,showWhen: false()
              ),
              #"SYSTEM_SYSRULES_dropdownField_v1"(
                label: "Position Sub-Type",
                placeholder: "-- Select Position Sub-Type --",
                choiceLabels: if(
                  and(ri!nomination.positionTypeId=#"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699",
                 toboolean(local!isOldVersion)=true),
                #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11636837",
                index(
                  local!subPositionTypes,
                  "subPosition",
                  null
                )),
                choiceValues: if(
                  and(
                    ri!nomination.positionTypeId=#"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699",
                 toboolean(local!isOldVersion)=true),
                #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11636843",
                index(
                  local!subPositionTypes,
                  "subPositionId",
                  null
                )),
                value: ri!nomination.subPositionTypeId,
                saveInto: {
                  ri!nomination.subPositionTypeId,
                  a!save(
                    ri!nomination.nonTraditionalTypeId,
                    null
                  ),
                  a!save(
                    ri!nomination.otherNonTraditionalRotationType,
                    null
                  ),
                  if(
                    or(
                      ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148688",
                      ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148695"
                    ),
                    {
                      a!save(ri!nomination.mdPromotionDate, null),
                      a!save(ri!nomination.isInspectionsReview, null)
                    },
                    a!save(ri!nomination.isAQR1or2, null)
                  ),
                  if(
                    ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148688",
                    a!save(
                      ri!nomination.partnerPromotionDate,
                      null
                    ),
                    {}
                  )
                },
                required: true,
                disabled: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!nomination.positionTypeId)
              ),
              #"SYSTEM_SYSRULES_dropdownField_v1"(
                label: "Non-Traditional Rotational Type",
                placeholder: "-- Select --",
                choiceLabels: index(
                  local!nonTraditionalRotationalTypes,
                  "nontradrotationaltype",
                  null
                ),
                choiceValues: index(
                  local!nonTraditionalRotationalTypes,
                  "nontradrotationid",
                  null
                ),
                value: ri!nomination.nonTraditionalTypeId,
                saveInto: {
                  ri!nomination.nonTraditionalTypeId,
                  a!save(
                    ri!nomination.otherNonTraditionalRotationType,
                    null
                  ),

                },
                required: and(
                  ri!nomination.subPositionTypeId = #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11599223",
                  /*if(*/
                    /*rule!CAW_isBlank(local!createdOnDate),*/
                    /*true,*/
                    /*if(*/
                      /*todatetime(local!createdOnDate) < cons!DRT_V3_DEPLOYMENT_DATE_TIME,*/
                      /*false,*/
                      /*true*/
                    /*)*/
                  /*)*/
                  toboolean(local!isOldVersion)=false
                ),
                showWhen: and(
                  ri!nomination.subPositionTypeId = #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11599223",
                  /*if(*/
                    /*rule!CAW_isBlank(local!createdOnDate),*/
                    /*true,*/
                    /*if(*/
                      /*todatetime(local!createdOnDate) < cons!DRT_V3_DEPLOYMENT_DATE_TIME,*/
                      /*false,*/
                      /*true*/
                    /*)*/
                  /*)*/
                  toboolean(local!isOldVersion)=false
                )
              ),
              #"SYSTEM_SYSRULES_textField"(
                label: "Other Non-Traditional Rotational Type",
                value: ri!nomination.otherNonTraditionalRotationType,
                saveInto: ri!nomination.otherNonTraditionalRotationType,
                validations: if(
                  regexmatch(
                    #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11586353",
                    ri!nomination.otherNonTraditionalRotationType
                  ),
                  #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11586372"[1],
                  {}
                ),
                required: ri!nomination.nonTraditionalTypeId = #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11599217",
                showWhen: ri!nomination.nonTraditionalTypeId = #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11599217",
                characterLimit: 100,
                showCharacterCount: true
              )
            }
          )
        }
      )
    }
  )
)
